fn find_min(a: &[i32], lo: usize) -> usize {
    // Initialize min index to the starting index
    let mut min_idx = lo;

    // Iterate over the subarray from the starting index to the end of the array
    for i in lo..a.len() {
        // Update min index if a smaller element is found
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }

    // Return the index of the minimal element
    min_idx
}

fn main() {
    let arr = [3, 1, 4, 1, 5, 9, 2, 6];
    let start_index = 2;
    let min_index = find_min(&arr, start_index);
    println!("The index of the minimal element from index {} is {}", start_index, min_index);
}